-- Source-reviewed IPA 2021-06-13 network and security questions.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q31','exam-fe','LAN接続装置','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問31・改編】LAN間接続装置について適切なものはどれか。','[{"id":"a","text":"ゲートウェイはOSI参照モデル第1〜3層だけのプロトコルを変換する"},{"id":"b","text":"ブリッジはIPアドレスに基づきフレームを中継する"},{"id":"c","text":"リピータは同種セグメント間で信号を増幅して伝送距離を延ばす"},{"id":"d","text":"ルータはMACアドレスに基づきフレームを中継する"}]','"c"','リピータは物理層の信号を再生・増幅して伝送範囲を延ばす。ブリッジはMAC、ルータはIPを用いる。 中文：中继器在物理层再生信号；网桥主要看MAC，路由器主要看IP。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q32','exam-fe','サブネット','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問32・改編】ネットワークアドレス200.170.70.16、サブネットマスク255.255.255.240のネットワークで、PCに割り当ててはいけないIPアドレスはどれか。','[{"id":"a","text":"200.170.70.17"},{"id":"b","text":"200.170.70.20"},{"id":"c","text":"200.170.70.30"},{"id":"d","text":"200.170.70.31"}]','"d"','/28の範囲は.16〜.31。.16はネットワーク、.31はブロードキャストで、ホストに使えるのは.17〜.30。 中文：该/28网段的.31是广播地址，不能分配给主机。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q33','exam-fe','NAPT','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問33・改編】LAN内の複数PCが、装置AのWAN側に割り当てた1個のグローバルIPアドレスを共有してインターネットを利用する。装置Aに必要な機能はどれか。','[{"id":"a","text":"DHCP"},{"id":"b","text":"NAPT（IPマスカレード）"},{"id":"c","text":"PPPoE"},{"id":"d","text":"パケットフィルタリング"}]','"b"','NAPTはIPアドレスとポート番号を変換して、複数端末が一つのグローバルIPを共有できる。 中文：NAPT通过地址和端口转换让多个终端共用一个公网IP。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q34','exam-fe','RARP','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問34・改編】TCP/IPネットワークでRARPの機能はどれか。','[{"id":"a","text":"IPパケットが通信先に到達するか調べる"},{"id":"b","text":"MACアドレスからIPアドレスを求める"},{"id":"c","text":"ドメイン名とホスト名からIPアドレスを求める"},{"id":"d","text":"プライベートIPとグローバルIPを相互変換する"}]','"b"','RARPはMACアドレスを手掛かりにIPアドレスを取得する旧来の方式。 中文：RARP根据MAC地址查询IP地址，是较早期的协议。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q35','exam-fe','CAPTCHA','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問35・改編】Webサイトで利用されるCAPTCHAに該当するものはどれか。','[{"id":"a","text":"アクセスした者に応答を求め、分析して人からのアクセスか確認する"},{"id":"b","text":"入力文字列をプレースホルダに割り当ててSQL文を組み立てる"},{"id":"c","text":"一定時間ごとに異なるパスワードを要求する"},{"id":"d","text":"サイトから送られた乱数を鍵としてパスワードを暗号化し返送する"}]','"a"','CAPTCHAは自動プログラムと人間の操作を区別するための応答検査。 中文：CAPTCHA通过响应测试区分人类操作与自动程序。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q36','exam-fe','ハッシュ関数','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問36・改編】ディジタル署名などに用いるハッシュ関数の特徴はどれか。','[{"id":"a","text":"同一ダイジェストを持つ異なる二つのメッセージを容易に求められる"},{"id":"b","text":"異なるメッセージでもダイジェストは全て同じになる"},{"id":"c","text":"メッセージダイジェストから元のメッセージを復元することは困難である"},{"id":"d","text":"ダイジェストの長さはメッセージの長さにより異なる"}]','"c"','暗号学的ハッシュ関数は原像を求めることが困難で、通常は固定長のダイジェストを出力する。 中文：密码学哈希具有原像难求性，输出通常为固定长度。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q37','exam-fe','RSA署名検証','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問37・改編】RSA方式のディジタル署名を検証するとき、検証鍵と使用方法はどれか。','[{"id":"a","text":"受信者の公開鍵を送信者が署名作成に使う"},{"id":"b","text":"受信者の秘密鍵を受信者が署名からダイジェストを算出する際に使う"},{"id":"c","text":"送信者の公開鍵を受信者が署名からダイジェストを算出する際に使う"},{"id":"d","text":"送信者の秘密鍵を送信者が署名作成に使う"}]','"c"','署名は送信者の秘密鍵で作成し、受信者は送信者の公開鍵で検証する。 中文：发送者用私钥签名，接收者用发送者的公钥验证。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q38','exam-fe','リバースブルートフォース','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問38・改編】リバースブルートフォース攻撃はどれか。','[{"id":"a","text":"入手済みIDとパスワードの組のリストでログインを試す"},{"id":"b","text":"一つのパスワードを選び、多数の利用者IDを試す"},{"id":"c","text":"IDと同じ文字列をパスワードとして組を生成し試す"},{"id":"d","text":"一つのIDを選び、多数のパスワードを試す"}]','"b"','一つの候補パスワードを複数の利用者IDに試す。ID固定でパスワードを総当たりする方式と逆。 中文：反向暴力破解固定一个密码，尝试多个用户ID。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q39','exam-fe','メール暗号化','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問39・改編】電子メールの本文を暗号化するために使用される方式はどれか。','[{"id":"a","text":"BASE64"},{"id":"b","text":"GZIP"},{"id":"c","text":"PNG"},{"id":"d","text":"S/MIME"}]','"d"','S/MIMEは電子メールの暗号化やディジタル署名を扱う。Base64は符号化、GZIPは圧縮、PNGは画像形式。 中文：S/MIME支持邮件加密及数字签名，Base64本身不是加密。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q40','exam-fe','SaaSの情報セキュリティ','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問40・改編】SaaSを利用する企業の情報セキュリティ管理について適切なものはどれか。','[{"id":"a","text":"システム運用を行わずに済むため、障害時の手順やバックアップの検討は不要"},{"id":"b","text":"アクセス管理を行わずに済むため、パスワードポリシの検討は不要"},{"id":"c","text":"システムを自社構築しないため、アプリケーション開発時のセキュリティ要件定義やシステムログ保存容量の設計が不要"},{"id":"d","text":"情報セキュリティ管理を行わずに済むため、管理規程や管理担当者は不要"}]','"c"','SaaS利用者はアプリケーション自体の開発・構築を通常行わないが、アカウント管理や障害対策など利用者側の責任は残る。 中文：使用SaaS通常无需自行开发和建设应用，但账户管理、故障应对等责任仍然存在。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
